export function sceneResult(scene,input){
 if(!scene)return false;
 if(scene.type==='part'||scene.type==='choice')return typeof input==='number'&&Number.isInteger(input)&&input===scene.target;
 if(scene.type==='scan')return Number(input)>=57&&Number(input)<=77;
 if(['dust','drive','dig'].includes(scene.type))return Number(input)>=85;
 if(scene.type==='reveal')return Number(input)>=80;
 if(scene.type==='layers')return Array.isArray(input)&&new Set(input.filter(x=>['crust','mantle','core'].includes(x))).size===3;
 return ['listen','ascent','laser'].includes(scene.type)&&input===true;
}
